+
+quint64 HexDataSourceView::wordValue(qint64 bit_offset) const
+{
+    quint64 value = 0;
+
+    if (word_encoding_ == ENC_LITTLE_ENDIAN) {
+        const int byte_offset = static_cast<int>(bit_offset / 8);
+        const unsigned byte_count = word_view_bits_ / 8;
+
+        for (unsigned byte = 0; byte < byte_count; byte++) {
+            if (byte_offset + static_cast<int>(byte) >= data_.size())
+                return 0;
+            value |= static_cast<quint64>(
+                static_cast<unsigned char>(data_[byte_offset + byte])) << (byte * 8);
+        }
+        return value;
+    }
+
+    for (unsigned bit = 0; bit < word_view_bits_; bit++) {
+        const qint64 absolute_bit = bit_offset + bit;
+        const int byte_offset = static_cast<int>(absolute_bit / 8);
+        const int bit_in_byte = 7 - static_cast<int>(absolute_bit % 8);
+
+        if (byte_offset < 0 || byte_offset >= data_.size())
+            return 0;
+
+        value = (value << 1) |
+                ((static_cast<unsigned char>(data_[byte_offset]) >> bit_in_byte) & 0x01);
+    }
+
+    return value;
+}
+
+QVector<quint16> HexDataSourceView::printableElementValues() const
+{
+    QVector<quint16> values;
+
+    if (word_view_bits_ <= 8) {
+        return values;
+    }
+
+    values.reserve(static_cast<qsizetype>(word_count_));
+    for (unsigned word = 0; word < word_count_; word++) {
+        const qint64 bit = word_bit_offset_ + static_cast<qint64>(word) * word_view_bits_;
+        if (bit + word_view_bits_ > static_cast<qint64>(data_.size()) * 8) {
+            break;
+        }
+        values.append(static_cast<quint16>(wordValue(bit)));
+    }
+
+    return values;
+}
+
+int HexDataSourceView::wordPanelChars() const
+{
+    int digits;
+
+    switch (recent.gui_bytes_view) {
+    case BYTES_HEX:
+        digits = (word_view_bits_ + 3) / 4;
+        break;
+    case BYTES_DEC:
+        digits = word_view_bits_ == 10 ? 4 : 5;
+        break;
+    case BYTES_OCT:
+        digits = (word_view_bits_ + 2) / 3;
+        break;
+    case BYTES_BITS:
+        digits = word_view_bits_;
+        break;
+    default:
+        ws_assert_not_reached();
+    }
+
+    // 16 words x (" " + digits), plus separators after each group of four.
+    return (16 * (digits + 1)) + 3;
+}
+
+int HexDataSourceView::wordRowBytes() const
+{
+    return static_cast<int>((16 * word_view_bits_ + 7) / 8);
+}
