+void HexDataSourceView::setWordInterpretation(QAction *action)
+{
+    if (!action) {
+        return;
+    }
+
+    if (action == action_words_8_) {
+        /*
+         * Leave the dissector-provided alignment metadata intact so the user
+         * can switch back without losing bit offset or word count.
+         */
+        word_view_bits_ = 8;
+        word_bit_offset_ = 0;
+        word_count_ = 0;
+        word_encoding_ = ENC_BIG_ENDIAN;
+        row_width_ = recent.gui_bytes_view == BYTES_BITS ? 8 : 16;
+    } else if (action == action_words_10_ || action == action_words_16_be_ ||
+               action == action_words_16_le_) {
+        const unsigned requested_bits = action == action_words_10_ ? 10 : 16;
+        const unsigned requested_encoding = action == action_words_16_le_ ?
+            ENC_LITTLE_ENDIAN : ENC_BIG_ENDIAN;
+        word_view_bits_ = requested_bits;
+        word_encoding_ = requested_encoding;
+        if (source_word_info_.word_bits == requested_bits && source_word_info_.word_count > 0) {
+            word_bit_offset_ = source_word_info_.bit_offset;
+            word_count_ = source_word_info_.word_count;
+        } else {
+            // No source hint is available: interpret complete words from bit zero.
+            word_bit_offset_ = 0;
+            word_count_ = static_cast<unsigned>(
+                (static_cast<quint64>(dataSize()) * 8) / requested_bits);
+        }
+        if (word_count_ > 0) {
+            row_width_ = wordRowBytes();
+            scrollToByte(0);
+        } else {
+            word_view_bits_ = 8;
+            word_encoding_ = ENC_BIG_ENDIAN;
+            row_width_ = recent.gui_bytes_view == BYTES_BITS ? 8 : 16;
+        }
+    }
+
+    updateContextMenu();
+    updateScrollbars();
+    viewport()->update();
+}
