+BaseDataSourceView *DataSourceTab::findDataSourceViewForOwner(const field_info *owner, int *idx)
+{
+    if (!owner) {
+        return nullptr;
+    }
+
+    // Use tab order so an owner with multiple derived sources consistently
+    // selects its first (usually least-transformed) representation.
+    for (int i = 0; i < count(); i++) {
+        QWidget *source = widget(i);
+        if (source_owners_.value(source, nullptr) == owner) {
+            BaseDataSourceView *view = qobject_cast<BaseDataSourceView *>(source);
+            if (view && idx) {
+                *idx = i;
+            }
+            return view;
+        }
+    }
+
+    return nullptr;
+}
