+void DataSourceTab::updateSourceVisibility(const field_info *selected)
+{
+    const field_info *owner = nullptr;
+    if (selected) {
+        // An owner field selects its scoped source directly. Other decoded
+        // fields use their own data source, including top-level protocols.
+        BaseDataSourceView *view = findDataSourceViewForOwner(selected);
+        if (!view) {
+            view = findDataSourceViewForTvb(selected->ds_tvb);
+        }
+        owner = source_owners_.value(view, nullptr);
+        if (!owner && selected->ds_tvb && selected->start >= 0 && selected->length > 0) {
+            // Transport fields still refer to the original packet. Choose the
+            // smallest enclosing payload range, not an enclosing protocol root.
+            for (const field_info *candidate : source_owners_) {
+                if (candidate && candidate->ds_tvb == selected->ds_tvb &&
+                    candidate->start >= 0 && candidate->length > 0 &&
+                    selected->start >= candidate->start &&
+                    static_cast<qint64>(selected->start) + selected->length <=
+                        static_cast<qint64>(candidate->start) + candidate->length &&
+                    (!owner || candidate->length < owner->length)) {
+                    owner = candidate;
+                }
+            }
+        }
+    }
+
+    // Reveal first, so hiding the previous payload never leaves all tabs hidden.
+    for (int i = 0; i < count(); i++) {
+        const field_info *candidate = source_owners_.value(widget(i), nullptr);
+        if (!candidate || candidate == owner) {
+            setTabVisible(i, true);
+        }
+    }
+    for (int i = 0; i < count(); i++) {
+        const field_info *candidate = source_owners_.value(widget(i), nullptr);
+        if (candidate && candidate != owner) {
+            setTabVisible(i, false);
+        }
+    }
+    setTabsVisible();
+}
